	for (let i = 0; i <= Math.ceil(cycleLengthMs / DAY_MS) + 2; i++) {
		const day = dayKey(new Date(start.getFullYear(), start.getMonth(), start.getDate() + i));
		if (day > last) break;
		out.push(slot(day));
