import { resetAtMs } from "./format.ts";

export function windowLabel(name: string): string {
	if (name === "weekly") return "Weekly";
	if (name === "monthly") return "Monthly";
	if (name === "5h" || name === "session" || name === "rolling") return "Session";
	return name;
}

/** `2026-09-29` -> `Sep 29 Mon` (local calendar, no timezone shift). */
export function formatDay(day: string): string {
	const [y, m, d] = day.split("-").map(Number);
	const date = new Date(y, (m ?? 1) - 1, d ?? 1);
	if (Number.isNaN(date.getTime())) return day;
	const md = date.toLocaleDateString("en-US", {
		month: "short",
		day: "numeric",
	});
	return `${md} ${date.toLocaleDateString("en-US", { weekday: "short" })}`;
}

/** `Oct 23` expiry; the card drops the date when the ticket has none. */
export function ticketExpiry(expiresAt: number, now = Date.now()): string {
	const ms = resetAtMs(expiresAt);
	if (ms == null || ms <= now) return "";
	const date = new Date(ms);
	if (Number.isNaN(date.getTime())) return "";
	const sameYear = date.getFullYear() === new Date(now).getFullYear();
	return date.toLocaleDateString("en-US", {
		month: "short",
		day: "numeric",
		...(!sameYear ? { year: "numeric" } : {}),
	});
}

/** When a ticket stops being spendable, or null for one without an expiry (i64::MAX) or one already gone. */
export function ticketExpiresMs(expiresAt: number, now = Date.now()): number | null {
	const ms = resetAtMs(expiresAt);
	if (ms == null || ms <= now || ms - now > 366 * DAY_MS) return null;
	return ms;
}

type TicketKind = { scope?: "all" | "model" | string; model?: string };

/** `Full` or the model a model reset is for (`Fable`). */
export function ticketKind(ticket: TicketKind): string {
	return ticket.scope === "model" ? (ticket.model ?? "Model") : "Full";
}

/** `Full reset`, `Fable reset`: the pill and dialog name, as claude.ai words it. */
export function ticketName(ticket: TicketKind): string {
	return `${ticketKind(ticket)} reset`;
}

/** What spending the ticket does, for its confirmation dialog. */
export function ticketEffect(ticket: TicketKind): string {
	if (ticket.scope !== "model") return "Clears your session and weekly usage now. This can't be undone.";
	const model = ticket.model ?? "this model's";
	return `Refills your session and ${model} allowance, and returns ${model} usage to your weekly limit. Other weekly usage stays. This can't be undone.`;
}

/** Tickets still spendable at `now`, soonest expiry first. */
export function liveTickets<T extends { expiresAt: number }>(tickets: readonly T[], now = Date.now()): T[] {
	return tickets
		.filter((ticket) => (resetAtMs(ticket.expiresAt) ?? Infinity) > now)
		.toSorted((a, b) => (resetAtMs(a.expiresAt) ?? Infinity) - (resetAtMs(b.expiresAt) ?? Infinity));
}

/**
 * The soonest live ticket that clears the weekly window. Only this one changes
 * the weekly pace: a model reset leaves the weekly usage in place.
 */
export function weeklyTicket<T extends { expiresAt: number } & TicketKind>(
	tickets: readonly T[],
	now = Date.now(),
): T | undefined {
	return liveTickets(tickets, now).find((ticket) => ticket.scope !== "model");
}

const TICKET_USE_VERBS: Record<string, string> = {
	reset: "Used",
	expired: "Expired unused",
	already_used: "Already used",
	ineligible: "Not eligible",
};

/** One ticket history row split for a table: verb, `Oct 23`, `00:55`, and `auto`/`manual` (none when it lapsed). */
export function ticketUseParts(use: { at: number; result: string; source: string } & TicketKind): {
	verb: string;
	kind: string;
	day: string;
	clock: string;
	source: string | null;
} {
	const date = new Date(resetAtMs(use.at) ?? 0);
	return {
		verb: TICKET_USE_VERBS[use.result] ?? use.result,
		kind: ticketKind(use),
		day: date.toLocaleDateString("en-US", { month: "short", day: "numeric" }),
		clock: date.toLocaleTimeString("en-GB", {
			hour: "2-digit",
			minute: "2-digit",
			hourCycle: "h23",
		}),
		source: use.result === "expired" ? null : use.source,
	};
}

/** One ticket history row: `Used Oct 23 00:55 · Fable reset · auto`. */
export function ticketUseLabel(use: { at: number; result: string; source: string } & TicketKind): string {
	const { verb, day, clock, source } = ticketUseParts(use);
	const head = `${verb} ${day} ${clock} · ${ticketName(use)}`;
	return source ? `${head} · ${source}` : head;
}

/**
 * `D-7` … `D-1` by calendar day inside the last week, `5h left` inside the last
 * 72 hours, `D-day` once it is gone, else "".
 */
export function ticketDday(expiresAt: number, now = Date.now()): string {
	const ms = resetAtMs(expiresAt) ?? now;
	const left = ms - now;
	if (left <= 0) return "D-day";
	if (left < 72 * 3_600_000) return `${Math.max(1, Math.ceil(left / 3_600_000))}h left`;
	// A midnight end belongs to the day before, as on the chart.
	const end = new Date(ms - 1);
	const today = new Date(now);
	const days = Math.round(
		(Date.UTC(end.getFullYear(), end.getMonth(), end.getDate()) -
			Date.UTC(today.getFullYear(), today.getMonth(), today.getDate())) /
			DAY_MS,
	);
	return days <= 7 ? `D-${days}` : "";
}

export type StripDay = {
	day: string;
	/** Used% that day; null when nothing was tracked or the day has not come yet. */
	pct: number | null;
	today: boolean;
	future: boolean;
	/** The day the window resets on. */
	reset: boolean;
};

const DAY_MS = 86_400_000;

export type SpendStripDay = {
	day: string;
	/** Cents spent that day; null for a day nothing was read (or a day yet to come). */
	cents: number | null;
	today: boolean;
	future: boolean;
};

/**
 * The calendar month of `now`, one slot per day, oldest first — the same basis
 * as a monthly quota window, but a prepaid balance has no reset to end the
 * month on, so the strip is the month itself.
 *
 * A day with no reading is an empty slot rather than a `$0.00`: the board only
 * knows the days it recorded.
 */
export function spendStrip(days: readonly { day: string; cents: number }[], now: number): SpendStripDay[] {
	const at = new Date(now);
	const today = dayKey(at);
	const spent = new Map(days.map((day) => [day.day, day.cents]));
	const lastDay = new Date(at.getFullYear(), at.getMonth() + 1, 0).getDate();
	const strip: SpendStripDay[] = [];
	for (let date = 1; date <= lastDay; date++) {
		const day = dayKey(new Date(at.getFullYear(), at.getMonth(), date));
		strip.push({
			day,
			cents: spent.get(day) ?? null,
			today: day === today,
			future: day > today,
		});
	}
	return strip;
}

/** Fewest days the zoomed month chart shows: one week, the closest a drag can close in. */
export const SPAN_MIN = 7;
/** Every day of the longest month, the widest the chart opens to. */
export const SPAN_MAX = 31;
/** Opens on one week, today in the middle, the same week a drag closes in to. */
export const SPAN_DEFAULT = SPAN_MIN;
/** Widest a window can be and still print a dollar label over every bar. */
export const SPAN_VALUES_MAX = 14;

/** A span a drag may ask for, kept inside the month and the chart's own limits. */
export function clampSpan(span: number, length: number): number {
	const most = Math.min(SPAN_MAX, Math.max(1, length));
	return Math.min(most, Math.max(Math.min(SPAN_MIN, most), Math.round(span)));
}

/**
 * The spans a drag steps through: each step halves or doubles the window, from
 * the week up to the whole month (a week, a fortnight, the month).
 */
export function spanLevels(length: number): number[] {
	const levels = [SPAN_MIN, SPAN_MIN * 2, length].map((span) => clampSpan(span, length));
	return [...new Set(levels)];
}

/** The level `steps` away from `span` (positive widens), held to the first and last level. */
export function stepSpan(span: number, steps: number, length: number): number {
	const levels = spanLevels(length);
	const from = levels.reduce(
		(best, level, i) => (Math.abs(level - span) < Math.abs(levels[best] - span) ? i : best),
		0,
	);
	return levels[Math.min(levels.length - 1, Math.max(0, from + steps))];
}

/**
 * The `span` slots of a month around today — three days behind and three ahead
 * by default — so the axis continues past today into the days still to come
 * instead of ending on it. A window that would run off the month slides back
 * inside it, and a strip with no today is returned from its first day.
 */
export function zoomedSpendStrip<T extends { today: boolean }>(strip: readonly T[], span: number): T[] {
	const today = strip.findIndex((slot) => slot.today);
	const width = clampSpan(span, strip.length);
	if (today < 0) return strip.slice(0, width);
	const before = Math.floor((width - 1) / 2);
	const start = Math.max(0, Math.min(today - before, strip.length - width));
	return strip.slice(start, start + width);
}

/**
 * What a day can spend and still stretch the credit over the rest of the month:
 * the balance divided by the days the strip has left, today included. Prepaid
 * has no reset, so the calendar month is the horizon. Null when there is nothing
 * left to spread.
 */
export function prepaidPerDayCents(
	balanceCents: number | null | undefined,
	strip: readonly { today: boolean }[],
): number | null {
	if (balanceCents == null || balanceCents <= 0) return null;
	const today = strip.findIndex((slot) => slot.today);
	const daysLeft = today < 0 ? 0 : strip.length - today;
	if (daysLeft <= 0) return null;
	return balanceCents / daysLeft;
}

export function dayKey(date: Date): string {
	const mm = String(date.getMonth() + 1).padStart(2, "0");
	const dd = String(date.getDate()).padStart(2, "0");
	return `${date.getFullYear()}-${mm}-${dd}`;
}

/**
 * One slot per local calendar day of the current cycle (start through reset day), so a quiet
 * day is an empty slot rather than a "0". Falls back to the tracked days when the cycle is unknown.
 */
export function cycleStrip(
	days: readonly { day: string; usedPercent: number }[],
	cycleLengthMs: number | undefined,
	resetMs: number | null,
	now: number,
): StripDay[] {
	const today = dayKey(new Date(now));
	const used = new Map(days.map((d) => [d.day, Math.round(d.usedPercent)]));
	const slot = (day: string): StripDay => ({
		day,
		pct: used.get(day) ?? null,
		today: day === today,
		future: day > today,
		reset: false,
	});
	if (!cycleLengthMs || resetMs == null) return days.map((d) => slot(d.day));
	// Providers jitter the reset by seconds; an hour of slack keeps a midnight reset from adding a slot.
	const cycleStart = new Date(resetMs - cycleLengthMs + 3_600_000);
	const earliest = days.reduce((min, d) => (d.day < min ? d.day : min), dayKey(cycleStart));
	const [sy, sm, sd] = earliest.split("-").map(Number);
	const start = new Date(sy, (sm ?? 1) - 1, sd ?? 1);
	// A reset at (or seconds past) local midnight belongs to the next cycle.
	const last = days.reduce((max, d) => (d.day > max ? d.day : max), dayKey(new Date(resetMs - 3_600_000)));
	const out: StripDay[] = [];
	for (let i = 0; i <= Math.ceil(cycleLengthMs / DAY_MS) + 2; i++) {
		const day = dayKey(new Date(start.getFullYear(), start.getMonth(), start.getDate() + i));
		if (day > last) break;
		out.push(slot(day));
	}
	// A cycle that starts and ends off midnight touches one calendar day more
	// than it has days; the trailing partial day repeats the first weekday, so
	// the strip keeps the cycle's own day count (7 for weekly, not 8).
	const cycleDays = Math.max(1, Math.round(cycleLengthMs / DAY_MS));
	if (out.length > cycleDays) out.length = cycleDays;
	const resetSlot = out.findLast((d) => d.day <= dayKey(new Date(resetMs - 3_600_000)));
	if (resetSlot) resetSlot.reset = true;
	return out;
}
